import { API_BASE_URL } from '../config/api';

export interface ChargeInput {
  amountCents: number;
  cardLast4: string;
}

export async function chargeCard(input: ChargeInput): Promise<{ chargeId: string }> {
  const response = await fetch(`${API_BASE_URL}/charges`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  });
  if (!response.ok) throw new Error(`Charge failed with status ${response.status}`);
  return (await response.json()) as { chargeId: string };
}

import { useCallback, useMemo, useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, SafeAreaView, KeyboardAvoidingView, Platform, ActivityIndicator } from 'react-native';
import { chargeCard } from '../services/charges';

const colors = {
  muted: '#8a8f8a',
  bg: '#0f120e',
  text: '#f5f5f0',
  accent: '#f05039',
  surface: '#1a1f1a',
  borderAlt: '#2a2f2a',
  danger: '#ff6b5e',
  success: '#4ade80',
}

const AMOUNT_CENTS = 7800;

const formatCardNumber = (raw: string): string =>
  raw.replace(/\D/g, '').slice(0, 16).replace(/(\d{4})(?=\d)/g, '$1 ');

const formatExpiry = (raw: string): string => {
  const digits = raw.replace(/\D/g, '').slice(0, 4);
  return digits.length > 2 ? `${digits.slice(0, 2)}/${digits.slice(2)}` : digits;
};

const isValidCard = (cardNumber: string): boolean => cardNumber.replace(/\s/g, '').length === 16;
const isValidExpiry = (expiry: string): boolean => /^(0[1-9]|1[0-2])\/\d{2}$/.test(expiry);
const isValidCvv = (cvv: string): boolean => /^\d{3}$/.test(cvv);

export function PaymentScreen(): JSX.Element {
  const [cardNumber, setCardNumber] = useState('');
  const [expiry, setExpiry] = useState('');
  const [cvv, setCvv] = useState('');
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  const valid = useMemo(
    () => isValidCard(cardNumber) && isValidExpiry(expiry) && isValidCvv(cvv) && !processing,
    [cardNumber, expiry, cvv, processing],
  );

  const pay = useCallback(async () => {
    if (!valid) return;
    setProcessing(true);
    setError(null);
    try {
      const { chargeId } = await chargeCard({ amountCents: AMOUNT_CENTS, cardLast4: cardNumber.replace(/\s/g, '').slice(-4) });
      setSuccess(chargeId);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Payment failed.');
    } finally {
      setProcessing(false);
    }
  }, [valid, cardNumber]);

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={styles.flex}>
        <View style={styles.content}>
          <Text style={styles.title}>Payment</Text>
          <Text style={styles.amount}>${(AMOUNT_CENTS / 100).toFixed(2)}</Text>
          <TextInput
            value={cardNumber}
            onChangeText={t => setCardNumber(formatCardNumber(t))}
            placeholder="Card number"
            placeholderTextColor="{colors.muted}"
            keyboardType="number-pad"
            accessibilityLabel="Card number"
            style={styles.input}
          />
          <View style={styles.row}>
            <TextInput
              value={expiry}
              onChangeText={t => setExpiry(formatExpiry(t))}
              placeholder="MM/YY"
              placeholderTextColor="{colors.muted}"
              keyboardType="number-pad"
              accessibilityLabel="Expiry date"
              style={[styles.input, styles.half]}
            />
            <TextInput
              value={cvv}
              onChangeText={t => setCvv(t.replace(/\D/g, '').slice(0, 3))}
              placeholder="CVV"
              placeholderTextColor="{colors.muted}"
              keyboardType="number-pad"
              secureTextEntry
              accessibilityLabel="CVV"
              style={[styles.input, styles.half]}
            />
          </View>
          {error && <Text style={styles.error}>{error}</Text>}
          {success && <Text style={styles.success}>Payment succeeded — {success}</Text>}
          <TouchableOpacity style={[styles.pay, !valid && styles.disabled]} disabled={!valid} onPress={pay} accessibilityRole="button">
            {processing ? <ActivityIndicator color="{colors.bg}" /> : <Text style={styles.payText}>Pay ${(AMOUNT_CENTS / 100).toFixed(2)}</Text>}
          </TouchableOpacity>
        </View>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  flex: { flex: 1 },
  content: { padding: 20 },
  title: { fontSize: 22, fontWeight: '700', color: colors.text },
  amount: { fontSize: 34, fontWeight: '800', color: colors.accent, marginVertical: 16 },
  input: { backgroundColor: colors.surface, color: colors.text, borderRadius: 6, padding: 14, marginBottom: 12, borderWidth: 1, borderColor: colors.borderAlt, fontSize: 16 },
  row: { flexDirection: 'row', gap: 12 },
  half: { flex: 1 },
  pay: { backgroundColor: colors.accent, borderRadius: 6, paddingVertical: 16, alignItems: 'center', marginTop: 8 },
  payText: { color: colors.bg, fontWeight: '700', fontSize: 16 },
  disabled: { opacity: 0.5 },
  error: { color: colors.danger, marginBottom: 8 },
  success: { color: colors.success, marginBottom: 8 },
});
